{
  "propositions": [
    {
      "id": "P1",
      "proposition": "An LEA must classify its employed school nurses as licensed personnel for purposes of Tennessee Code Annotated, Section 49-3-306, and compensate them according to its licensed-personnel salary schedule for the respective school year.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "An LEA shall classify school nurses employed by the LEA as licensed\n\n personnel for purposes of this section and shall compensate school nurses\n\n according to the salary schedule adopted by the LEA for licensed personnel for\n\n the respective school year."
    },
    {
      "id": "P2",
      "proposition": "The new subsection does not limit an LEA's ability to contract with the Tennessee public school nurse program created by § 68-1-1201 for school health services or to set contract terms, including school nurse compensation; it does not apply to compensation paid to LEA contractors.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "This subsection (j) does not limit or restrict an LEA's\n\n ability to contract with the Tennessee public school nurse program, created by §\n\n 68-1-1201, for the provision of school health services, or to set the terms of such\n\n a contract, including the compensation for a school nurse. This subsection (j)\n\n does not apply to compensation paid to contractors of the LEA."
    },
    {
      "id": "P3",
      "proposition": "An LEA-employed school nurse with a valid registered professional nursing license, Nationally Certified School Nurse credentials from the National Board for Certification of School Nurses, and zero years of experience must receive the same base salary for the respective school year as a licensed teacher with a bachelor's degree and zero years of experience.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "School nurses must receive the same base salary, for the\n\n respective school year, as that established for licensed teachers with a\n\n bachelor's degree and zero (0) years of experience, if the school nurse:"
    },
    {
      "id": "P4",
      "proposition": "LEA-employed school nurses with more training and experience than identified in subdivision (j)(2)(A) must receive more than the base salary per school year.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "School nurses employed by the LEA who have more training\n\n and experience than the training and experience identified in subdivision\n\n (j)(2)(A) must receive more than the base salary per school year."
    },
    {
      "id": "P5",
      "proposition": "LEA-employed school nurses with less training and experience than identified in subdivision (j)(2)(A) must receive less than the base salary per school year.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "School nurses employed by the LEA who have less training\n\n and experience than the training and experience identified in subdivision\n\n (j)(2)(A) must receive less than the base salary per school year."
    },
    {
      "id": "P6",
      "proposition": "A salary schedule adopted pursuant to § 49-3-306(a)(1) may not reduce the salary of a school nurse employed by the LEA when the schedule is adopted.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "A salary schedule adopted pursuant to subdivision (a)(1) shall not\n\n result in the reduction of the salary of a school nurse employed by the LEA at the\n\n time of the adoption of the salary schedule."
    },
    {
      "id": "P7",
      "proposition": "The act takes effect July 1, 2026, and applies to the 2026-2027 school year and every school year thereafter.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect July 1, 2026, the public welfare requiring it, and\n\napplies to the 2026-2027 school year and each school year thereafter."
    }
  ]
}
